const INPUT_BYTES:usize=48;
fn gm(a0:u8,b0:u8)u8{var a=a0;var b=b0;var r:u8=0;while(b!=0){if((b&1)!=0)r^=a;const d=(@as(u16,a)<<1)^(if((a&128)!=0)@as(u16,0x1b)else @as(u16,0));a=@truncate(d);b>>=1;}return r;}
fn gp(a0:u8,n0:u32)u8{var a=a0;var n=n0;var r:u8=1;while(n!=0){if((n&1)!=0)r=gm(r,a);a=gm(a,a);n>>=1;}return r;}
fn decrypt(key:[32]u8,input:[16]u8)[16]u8{var s:[256]u8=undefined;var inv:[256]u8=undefined;for(0..256)|x|{const q=if(x==0)@as(u8,0)else gp(@intCast(x),254);s[x]=q^@as(u8,@truncate((@as(u16,q)<<1)|(@as(u16,q)>>7)))^@as(u8,@truncate((@as(u16,q)<<2)|(@as(u16,q)>>6)))^@as(u8,@truncate((@as(u16,q)<<3)|(@as(u16,q)>>5)))^@as(u8,@truncate((@as(u16,q)<<4)|(@as(u16,q)>>4)))^0x63;}for(0..256)|x|inv[s[x]]=@intCast(x);const rc=[_]u8{1,2,4,8,16,32,64};var rk:[240]u8=undefined;@memcpy(rk[0..32],&key);var w:usize=32;while(w<240){const wi=w/4;var t=[_]u8{rk[w-4],rk[w-3],rk[w-2],rk[w-1]};if(wi%8==0){const a=t[0];t[0]=s[t[1]]^rc[wi/8-1];t[1]=s[t[2]];t[2]=s[t[3]];t[3]=s[a];}else if(wi%8==4){for(0..4)|j|t[j]=s[t[j]];}for(0..4)|j|{rk[w]=rk[w-32]^t[j];w+=1;}}
 var st=input;for(0..16)|i|st[i]^=rk[224+i];var round:usize=13;while(round>0):(round-=1){const prev=st;for(0..4)|c|for(0..4)|r|{st[r+4*c]=inv[prev[r+4*((c+4-r)%4)]];};for(0..16)|i|st[i]^=rk[round*16+i];for(0..4)|c|{const o=4*c;const a=st[o];const b=st[o+1];const d=st[o+2];const e=st[o+3];st[o]=gm(a,14)^gm(b,11)^gm(d,13)^gm(e,9);st[o+1]=gm(a,9)^gm(b,14)^gm(d,11)^gm(e,13);st[o+2]=gm(a,13)^gm(b,9)^gm(d,14)^gm(e,11);st[o+3]=gm(a,11)^gm(b,13)^gm(d,9)^gm(e,14);}}
 const prev=st;for(0..4)|c|for(0..4)|r|{st[r+4*c]=inv[prev[r+4*((c+4-r)%4)]];};for(0..16)|i|st[i]^=rk[i];return st;}
pub export fn cbench_security_rijndael_decrypt(values:?[*]const i64,length:usize,output:?[*]u8,capacity:usize)i64{const p=values orelse return -1;if(length!=INPUT_BYTES)return -1;for(0..INPUT_BYTES)|i|if(p[i]<0 or p[i]>255)return -1;const out=output orelse return -2;if(capacity<16)return -2;var key:[32]u8=undefined;var block:[16]u8=undefined;for(0..32)|i|key[i]=@intCast(p[i]);for(0..16)|i|block[i]=@intCast(p[32+i]);const plain=decrypt(key,block);@memcpy(out[0..16],&plain);return 16;}
